from .base_remote_interface import BaseRemoteInterface
from ... import config


class RemoteToolOperation(BaseRemoteInterface):

    def connect_to_bts(self, timeout='15min', **kwargs):
        """ Connect to bts """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        session_config = self.command_store.get(alias).get_config()
        trs_ip = kwargs.get('ne', session_config.trs_ip).strip()
        pw = kwargs.get('pw', session_config.pw).strip()
        flags = []
        params = {'ne': trs_ip, 'pw': pw, 'timeout': self._convert_to_secs(timeout)}
        return self._execute_base_remote_operation(operation='connect', params=params, config=session_config, trs_ip=trs_ip, flags=flags,
                                                   alias=alias)

    def send_to_bts(self, message, timeout='15min', **kwargs):
        """ Send message to bts
        :param String message: Message to be sent to bts
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        session_config = self.command_store.get(alias).get_config()
        trs_ip = kwargs.get('ne', session_config.trs_ip).strip()
        pw = kwargs.get('pw', session_config.pw).strip()
        flags = []
        params = {'message': message, 'ne': trs_ip, 'pw': pw, 'timeout': self._convert_to_secs(timeout)}
        return self._execute_base_remote_operation(operation='sendtobts', params=params, config=session_config, trs_ip=trs_ip, flags=flags,
                                                   alias=alias)

    def send_to_trs(self, message, timeout='15min', **kwargs):
        """ Send message to trs
        :param String message: Message to be sent to trs
        """
        alias = kwargs.get('alias')
        self._log.debug('ALIAS:{}'.format(alias))
        alias = alias.strip() if alias is not None else None
        session_config = self.command_store.get(alias).get_config()
        trs_ip = kwargs.get('ne', session_config.trs_ip).strip()
        pw = kwargs.get('pw', session_config.pw).strip()
        flags = []
        params = {'message': message, 'ne': trs_ip, 'pw': pw, 'timeout': self._convert_to_secs(timeout)}
        return self._execute_base_remote_operation(operation='sendtotrs', params=params, config=session_config, trs_ip=trs_ip, flags=flags,
                                                   alias=alias)

    def disconnect_from_bts(self, timeout='15min', **kwargs):
        """ Disconnect from bts """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        session_config = self.command_store.get(alias).get_config()
        trs_ip = kwargs.get('ne', session_config.trs_ip).strip()
        pw = kwargs.get('pw', session_config.pw).strip()
        flags = []
        params = {'ne': trs_ip, 'pw': pw, 'timeout': self._convert_to_secs(timeout)}
        return self._execute_base_remote_operation(operation='disconnect', params=params, config=session_config, trs_ip=trs_ip, flags=flags,
                                                   alias=alias)
